package com.hotel.hotel_backend.controller;
import com.hotel.hotel_backend.model.Hotel;import com.hotel.hotel_backend.repository.HotelRepository;import com.hotel.hotel_backend.repository.UserRepository;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hotels") public class HotelController {
 private final HotelRepository hotels;private final UserRepository users;public HotelController(HotelRepository hotels,UserRepository users){this.hotels=hotels;this.users=users;}
 @GetMapping public List<Hotel> all(@RequestParam(required=false) String city){if(city==null||city.isBlank())return hotels.findByStatus("APPROVED");return hotels.findByCityContainingIgnoreCaseAndStatus(city,"APPROVED");}
 @GetMapping("/{id}") public Hotel one(@PathVariable Long id){return hotels.findById(id).filter(h->"APPROVED".equalsIgnoreCase(h.getStatus())).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Hotel not found"));}
 @GetMapping("/owner/mine") public List<Hotel> mine(Authentication auth){var owner=users.findByEmail(auth.getName()).orElseThrow();return hotels.findByOwnerId(owner.getId());}
 @PostMapping("/owner") public ResponseEntity<Hotel> create(@RequestBody Hotel hotel,Authentication auth){var owner=users.findByEmail(auth.getName()).orElseThrow();hotel.setId(null);hotel.setOwnerId(owner.getId());hotel.setStatus("PENDING");return ResponseEntity.status(201).body(hotels.save(hotel));}
 @PutMapping("/owner/{id}") public ResponseEntity<Hotel> update(@PathVariable Long id,@RequestBody Hotel changes,Authentication auth){var owner=users.findByEmail(auth.getName()).orElseThrow();Hotel h=hotels.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(h.getOwnerId(),owner.getId()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN);h.setName(changes.getName());h.setCity(changes.getCity());h.setLocation(changes.getLocation());h.setLandmark(changes.getLandmark());h.setFacilities(changes.getFacilities());h.setImageUrl(changes.getImageUrl());h.setStartingPrice(changes.getStartingPrice());h.setStatus("PENDING");return ResponseEntity.ok(hotels.save(h));}
 @GetMapping("/admin/pending") public List<Hotel> pending(){return hotels.findByStatus("PENDING");}
 @PutMapping("/admin/{id}/decision") public ResponseEntity<Hotel> decide(@PathVariable Long id,@RequestParam String status){if(!List.of("APPROVED","REJECTED").contains(status.toUpperCase()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Status must be APPROVED or REJECTED");Hotel h=hotels.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));h.setStatus(status.toUpperCase());return ResponseEntity.ok(hotels.save(h));}
}
